function brightnessLabel(score) {
  if (score < 25) return "こもりぎみ・低め";
  if (score < 45) return "落ち着いた響き";
  if (score < 60) return "バランス型";
  if (score < 80) return "抜けが良い";
  return "きらびやかな倍音";
}

